package com.example.data.repository

import com.example.data.model.BrochureSortOption
import com.example.data.model.Medicine
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.time.LocalDate

class MedicineRepository {

    private val _medicines = MutableStateFlow<List<Medicine>>(initialMedicineList)
    val medicines: StateFlow<List<Medicine>> = _medicines.asStateFlow()

    fun getAllMedicines(): List<Medicine> = _medicines.value

    fun getMedicineById(id: String): Medicine? = _medicines.value.find { it.id == id }

    fun getCompanies(): List<String> {
        val all = _medicines.value.map { it.company }.distinct().sorted()
        return listOf("الكل") + all
    }

    fun getCategories(): List<String> {
        val all = _medicines.value.map { it.form }.distinct().sorted()
        return listOf("الكل") + all
    }

    // Filter and Sort medicines
    fun filterAndSort(
        query: String = "",
        company: String = "الكل",
        form: String = "الكل",
        onlyWithBonus: Boolean = false,
        sortOption: BrochureSortOption = BrochureSortOption.NAME_ASC
    ): List<Medicine> {
        var list = _medicines.value

        if (company != "الكل") {
            list = list.filter { it.company.trim() == company.trim() }
        }

        if (form != "الكل") {
            list = list.filter { it.form.contains(form, ignoreCase = true) }
        }

        if (onlyWithBonus) {
            list = list.filter { it.bonusFree > 0 }
        }

        if (query.isNotBlank()) {
            val q = query.trim().lowercase()
            list = list.filter {
                it.name.lowercase().contains(q) ||
                it.company.lowercase().contains(q) ||
                it.activeIngredient.lowercase().contains(q) ||
                it.form.lowercase().contains(q) ||
                it.dosage.lowercase().contains(q)
            }
        }

        // Apply sorting
        return when (sortOption) {
            BrochureSortOption.NAME_ASC -> list.sortedBy { it.name }
            BrochureSortOption.BONUS_DESC -> list.sortedByDescending { 
                if (it.bonusPaid > 0) (it.bonusFree.toDouble() / it.bonusPaid.toDouble()) else 0.0 
            }
            BrochureSortOption.PRICE_ASC -> list.sortedBy { it.price }
            BrochureSortOption.PRICE_DESC -> list.sortedByDescending { it.price }
            BrochureSortOption.COMPANY_ASC -> list.sortedBy { it.company }
        }
    }

    // Update medicine price (for price drop alert simulation & push notifications)
    fun updateMedicinePrice(medicineId: String, newPrice: Double): Medicine? {
        val currentList = _medicines.value.toMutableList()
        val index = currentList.indexOfFirst { it.id == medicineId }
        if (index != -1) {
            val oldMed = currentList[index]
            val updatedMed = oldMed.copy(
                oldPrice = oldMed.price,
                price = newPrice
            )
            currentList[index] = updatedMed
            _medicines.value = currentList
            return updatedMed
        }
        return null
    }

    // Update or add special bonus promotion
    fun applySpecialPromotion(medicineId: String, newBonus: String, bonusPaid: Int, bonusFree: Int): Medicine? {
        val currentList = _medicines.value.toMutableList()
        val index = currentList.indexOfFirst { it.id == medicineId }
        if (index != -1) {
            val oldMed = currentList[index]
            val updatedMed = oldMed.copy(
                bonus = newBonus,
                bonusPaid = bonusPaid,
                bonusFree = bonusFree,
                isPromoted = true
            )
            currentList[index] = updatedMed
            _medicines.value = currentList
            return updatedMed
        }
        return null
    }

